-- ---------------------------------------------------------------------------
-- Travel transactions + frozen invoices.
--
-- * ids are application-generated (txn_<uuid v4> / inv_<uuid v4>), so no
--   surrogate/generated columns are needed anywhere; if one ever is, it must
--   use BIGINT GENERATED BY DEFAULT AS IDENTITY (not AUTO_INCREMENT) to stay
--   Postgres-portable.
-- * all money is BIGINT minor units (scale 2, e.g. cents); IEEE floats are
--   never stored.
-- * transaction identity is a UNIQUE constraint on external_id, enforced by
--   the database so overlapping POSTs cannot insert a second row.
-- * invoices are frozen snapshots: invoice_items stores copies of the
--   transaction state, and invoice_*_rollup tables store pre-aggregated
--   rollups so GET cost is independent of item count.
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS transactions (
    id          VARCHAR(64)  NOT NULL PRIMARY KEY,
    external_id VARCHAR(255) NOT NULL,
    type        VARCHAR(32)  NOT NULL,
    currency    CHAR(3)      NOT NULL,
    occurred_at TIMESTAMP(6) NOT NULL,
    total_minor BIGINT       NOT NULL CHECK (total_minor >= 0),
    -- derived from metadata for navan_fee rows, NULL otherwise (queryable, not JSON-only)
    fee_kind    VARCHAR(32),
    metadata    TEXT         NOT NULL,
    created_at  TIMESTAMP(6) NOT NULL,
    updated_at  TIMESTAMP(6) NOT NULL,
    CONSTRAINT ux_transactions_external_id UNIQUE (external_id)
);

CREATE INDEX IF NOT EXISTS idx_transactions_created ON transactions (created_at, id);

CREATE TABLE IF NOT EXISTS transaction_tax_lines (
    transaction_id VARCHAR(64)  NOT NULL REFERENCES transactions (id) ON DELETE CASCADE,
    position       INT          NOT NULL,
    name           VARCHAR(100) NOT NULL,
    rate           DECIMAL(7, 4),
    amount_minor   BIGINT       NOT NULL CHECK (amount_minor >= 0),
    PRIMARY KEY (transaction_id, position)
);

CREATE TABLE IF NOT EXISTS transaction_fee_lines (
    transaction_id VARCHAR(64)  NOT NULL REFERENCES transactions (id) ON DELETE CASCADE,
    position       INT          NOT NULL,
    name           VARCHAR(100) NOT NULL,
    amount_minor   BIGINT       NOT NULL CHECK (amount_minor >= 0),
    PRIMARY KEY (transaction_id, position)
);

CREATE TABLE IF NOT EXISTS invoices (
    id           VARCHAR(64) NOT NULL PRIMARY KEY,
    currency     CHAR(3)     NOT NULL,
    total_minor  BIGINT      NOT NULL CHECK (total_minor >= 0),
    item_count   INT         NOT NULL,
    -- SHA-256 of the sorted transaction ids joined with '\n'; the uniqueness
    -- constraint is what rejects concurrent identical invoice creation.
    txn_set_hash CHAR(64)    NOT NULL,
    created_at   TIMESTAMP(6) NOT NULL,
    updated_at   TIMESTAMP(6) NOT NULL,
    CONSTRAINT ux_invoices_txn_set_hash UNIQUE (txn_set_hash)
);

CREATE INDEX IF NOT EXISTS idx_invoices_created ON invoices (created_at, id);

CREATE TABLE IF NOT EXISTS invoice_items (
    invoice_id         VARCHAR(64)  NOT NULL REFERENCES invoices (id) ON DELETE CASCADE,
    position           INT          NOT NULL,
    transaction_id     VARCHAR(64)  NOT NULL REFERENCES transactions (id) ON DELETE RESTRICT,
    external_id        VARCHAR(255) NOT NULL,
    type               VARCHAR(32)  NOT NULL,
    currency           CHAR(3)      NOT NULL,
    occurred_at        TIMESTAMP(6) NOT NULL,
    total_minor        BIGINT       NOT NULL CHECK (total_minor >= 0),
    fee_kind           VARCHAR(32),
    -- verbatim copies of the transaction state at invoice time (not a live join)
    metadata_snapshot  TEXT         NOT NULL,
    tax_lines_snapshot TEXT         NOT NULL,
    fee_lines_snapshot TEXT         NOT NULL,
    PRIMARY KEY (invoice_id, position),
    CONSTRAINT ux_invoice_items_transaction UNIQUE (invoice_id, transaction_id)
);

-- "is this transaction on an invoice?" (PATCH/DELETE 409 check)
CREATE INDEX IF NOT EXISTS idx_invoice_items_tx ON invoice_items (transaction_id);

-- Stored rollups, written once at create/PATCH so reads never aggregate.
CREATE TABLE IF NOT EXISTS invoice_tax_rollup (
    invoice_id   VARCHAR(64)  NOT NULL REFERENCES invoices (id) ON DELETE CASCADE,
    position     INT          NOT NULL,
    name         VARCHAR(100) NOT NULL,
    rate         DECIMAL(7, 4),
    amount_minor BIGINT       NOT NULL,
    PRIMARY KEY (invoice_id, position)
);

CREATE TABLE IF NOT EXISTS invoice_fee_rollup (
    invoice_id   VARCHAR(64)  NOT NULL REFERENCES invoices (id) ON DELETE CASCADE,
    position     INT          NOT NULL,
    name         VARCHAR(100) NOT NULL,
    amount_minor BIGINT       NOT NULL,
    PRIMARY KEY (invoice_id, position)
);
